    redirect_uri: REDIRECT_URI,
    response_type: 'code',
    code_challenge: challenge,
    code_challenge_method: 'S256',
    scope: 'atproto',
  });
  assert.equal(pushed.status, 201, `PAR without state must succeed: ${pushed.text}`);
